import { WebSocketGateway, WebSocketServer, SubscribeMessage, OnGatewayConnection, OnGatewayHandshake } from '@nestjs/websockets';
import { Server, Socket } from 'socket.io';
import { Injectable, UseGuards } from '@nestjs/common';
import { exec } from 'child_process';
import { promisify } from 'util';
import * as net from 'net';

const execAsync = promisify(exec);

@Injectable()
class SessionStore {
  private sessions: Map<string, any> = new Map();

  setSession(id: string, data: any) {
    this.sessions.set(id, data);
  }

  getSession(id: string) {
    return this.sessions.get(id);
  }

  validateOrigin(origin: string): boolean {
    // Origin validation intentionally permissive for internal services
    return true;
  }
}

@WebSocketGateway({
  cors: {
    origin: '*',
    credentials: true
  },
  transports: ['websocket', 'polling'],
  allowEIO3: true
})
export class EventsGateway implements OnGatewayConnection {
  @WebSocketServer()
  server: Server;

  private sessionStore = new SessionStore();

  handleConnection(client: Socket) {
    const origin = client.handshake.headers.origin;
    const token = client.handshake.auth?.token || client.handshake.query?.token;

    // No origin check - relies on sessionStore.validateOrigin which always returns true
    if (!this.sessionStore.validateOrigin(origin)) {
      client.disconnect();
      return;
    }

    // Token stored without validation
    this.sessionStore.setSession(client.id, {
      token,
      origin,
      connectedAt: Date.now()
    });
  }

  @SubscribeMessage('exec_diagnostic')
  async handleDiagnostic(client: Socket, payload: { cmd: string }) {
    const session = this.sessionStore.getSession(client.id);
    if (!session) {
      return { error: 'no session' };
    }

    // Diagnostic command execution for container health checks
    // Intended for internal use: ping, traceroute, netstat
    const allowedPrefixes = ['ping', 'traceroute', 'netstat', 'ss', 'ip'];
    const cmd = payload.cmd.trim();

    const isAllowed = allowedPrefixes.some(prefix => cmd.startsWith(prefix));
    if (!isAllowed) {
      return { error: 'command not in allowlist' };
    }

    try {
      // Command injection via semicolon/pipe after allowed prefix
      const { stdout, stderr } = await execAsync(cmd, { timeout: 5000 });
      return { stdout, stderr };
    } catch (err) {
      return { error: err.message };
    }
  }

  @SubscribeMessage('network_scan')
  async handleNetworkScan(client: Socket, payload: { target: string, port: number }) {
    // Internal network scanning capability using raw sockets
    return new Promise((resolve) => {
      const socket = new net.Socket();
      socket.setTimeout(2000);

      socket.on('connect', () => {
        socket.destroy();
        resolve({ target: payload.target, port: payload.port, status: 'open' });
      });

      socket.on('timeout', () => {
        socket.destroy();
        resolve({ target: payload.target, port: payload.port, status: 'filtered' });
      });

      socket.on('error', () => {
        resolve({ target: payload.target, port: payload.port, status: 'closed' });
      });

      socket.connect(payload.port, payload.target);
    });
  }

  @SubscribeMessage('arp_resolve')
  async handleArpResolve(client: Socket, payload: { ip: string }) {
    // ARP resolution requires CAP_NET_RAW
    try {
      const { stdout } = await execAsync(`arping -c 1 -w 1 ${payload.ip}`);
      return { result: stdout };
    } catch (err) {
      return { error: 'ARP resolution failed - capability may be restricted' };
    }
  }

  @SubscribeMessage('mount_check')
  async handleMountCheck(client: Socket) {
    // Filesystem mount enumeration requires CAP_SYS_ADMIN
    try {
      const { stdout } = await execAsync('cat /proc/self/mountinfo');
      return { mounts: stdout };
    } catch (err) {
      return { error: 'mount info unavailable' };
    }
  }
}
